mapper.select:
select * from ( SELECT DISTINCT case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then NULL else ten.tenant_id end AS tenantId, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then NULL else ten.tenant_name end AS tenantName, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then '999999' else ten.province_id end AS provinceId, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then '未知' else pro.area_name end AS provinceName, NULL AS proParentCode, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then ten.tenant_id else ten.city_id end AS cityId, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then ten.tenant_name else city.area_name end AS cityName, '1' AS proLevel, '2' AS cityLevel, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then NULL else '3' end AS tenantLevel, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then '999999' WHEN city.area_parent_code IS NULL or city.area_parent_code = '' THEN pro.area_code else city.area_parent_code end AS cityParentCode, case when ten.province_id IS NULL OR ten.city_id IS NULL OR ten.city_id = '' OR ten.province_id = '' then NULL else ten.city_id end AS tenParentCode FROM sys_tenant_info ten LEFT JOIN sys_area pro ON pro.area_code = ten.province_id LEFT JOIN sys_area city ON city.area_code = ten.city_id LEFT JOIN sys_user u ON u.tenant_id = ten.tenant_id and u.is_tenant_admin=1 and u.del_flag = '0' WHERE ten.del_flag = '0'
and ten.tenant_id = #{param.customerCode}
AND ten.is_operation in
#{labelIdItem}
and u.USER_NAME like concat('%',#{param.tenantManager},'%')
and ten.is_operation = #{param.isOperation}
) a order by a.provinceId

select tenant_id
from sys_tenant_cascade_rel
where plat_code = #{platCode}

SELECT count( distinct device_code ) as "devNum", tenant_id as "customerCode" FROM vm_order_devices WHERE delete_flag = '0' and ord_status in ('0','1','2')
AND tenant_id in
#{labelIdItem}
GROUP BY tenant_id;

SELECT count( tenant_id ) as "orderNum", tenant_id as "customerCode" FROM vm_order_customer WHERE 1=1
AND tenant_id in
#{labelIdItem}
GROUP BY tenant_id;

SELECT count( tenant_id ) as "orderNum", tenant_id as "customerCode" FROM vm_order_customer WHERE delete_flag = '0' AND ord_status IN ('0', '1', '2')
AND tenant_id in
#{labelIdItem}
GROUP BY tenant_id;

