update sys_tenant_info set is_operation = #{isOperation},
operation_modifier_date = now(),operation_modifier = #{operationModifier}
where tenant_id IN

    #{labelIdItem}

update.foreach:
update sys_tenant_operation_config set delete_flag = 1,is_operation = 0,
update_time = now(),modifier = #{tenantInfo.operationModifier}
where tenant_id = #{tenantInfo.tenantId} and accept_node = #{tenantInfo.locationCode}
and industry_code = #{tenantInfo.industryCode} and app_ver_code = #{tenantInfo.appVerCode}

mapper.select:
SELECT t.tenant_id,t.tenant_name FROM sys_tenant_info t WHERE t.del_flag = '0' ${param.dataScope}
and t.tenant_id in ( SELECT DISTINCT tenant_id customerCode FROM vm_order_customer WHERE (NOW() > valid_time AND invalid_time > NOW() OR invalid_time IS NULL OR invalid_time = '') AND ord_status IN ('0', '1', '2') AND delete_flag = '0' )
AND (t.tenant_id LIKE CONCAT(CONCAT('%',#{param.keyword},'%')) OR (t.tenant_name LIKE CONCAT(CONCAT('%',#{param.keyword},'%'))))
AND t.tenant_id in
#{labelIdItem}

SELECT reg.id, reg.tenant_id as customerCode, reg.tenant_name as customerName, reg.app_key as appKey, reg.secret_key as secretKey, reg.is_open as isOpen FROM sys_auth_register_api reg WHERE 1 = 1
and reg.tenant_id = #{customerCode}
and reg.is_open = #{isOpen}
limit 1

SELECT
func.api_intf_code apiIntfCode,
func.api_intf_name apiIntfName,
func.api_intf_type as apiIntfType,
func.callback_url AS callbackUrl
FROM
sys_auth_register_func_api func
WHERE
func.delete_flag = '1'
and func.register_id =  #{registerId}

    and func.status = #{status}

SELECT t2.api_intf_code apiIntfCode, t2.api_intf_name apiIntfName, t2.api_intf_type as apiIntfType, t2.callback_url AS callbackUrl, t2.delete_flag AS deleteFlag, t2.status AS status FROM sys_auth_register_api t1 left join sys_auth_register_func_api t2 on t1.id = t2.register_id WHERE 1 = 1
and t2.register_id = #{registerId}
and t2.delete_flag = #{deleteFlag}
and t2.status = #{status}
and t1.tenant_id = #{customerCode}

mapper.insert:
insert into sys_auth_register_func_api (
register_id, callback_url, create_time,  delete_flag,api_intf_name,api_intf_code,api_intf_type
)
values

    (
    #{item.registerId},#{item.callbackUrl},now(),'1',#{item.apiIntfName},#{item.apiIntfCode},#{item.apiIntfType}
    )

mapper.update:
update sys_auth_register_func_api t1 ,sys_auth_register_api t2


        t1.status = #{status},


        t1.delete_flag = #{deleteFlag},



where t1.register_id = t2.id

    and t1.register_id = #{registerId}


    and t2.tenant_id = #{customerCode}


    and t1.status = #{oldStatus}


    and t1.delete_flag = #{oldDeleteFlag}

update sys_auth_register_api set is_open = #{isOpen},open_modifier_date = now(),open_modifier = #{openModifier}
where 1=1

    and id = #{id}


    and tenant_id = #{customerCode}

mapper.select:
SELECT REMARK FROM sys_dict_data WHERE status = '0' AND DICT_TYPE = #{enumTypeId}
AND dict_value in
#{labelIdItem}

mapper.update:
update sys_tenant_operation_config set delete_flag = 1,modifier = #{param.modifier},is_operation = 0
where tenant_id = #{param.tenantId}
and accept_node = #{param.acceptNode}
and industry_code = #{param.industryCode}
and app_ver_code = #{param.appVerCode}

mapper.select:
SELECT api_intf_id as apiIntfId, api_intf_name as apiIntfName, api_intf_type as apiIntfType, call_route as callRoute, is_open as isOpen, open_privilege as openPrivilege FROM api_intf_info
AND api_intf_type = #{apiIntfType}
AND is_open = #{isOpen}
AND open_privilege = #{openPrivilege}
ORDER BY api_intf_id asc

SELECT DISTINCT tenant_id customerCode FROM vm_order_customer WHERE ord_status IN ('0', '1', '2') AND delete_flag = '0'
AND tenant_id in
#{labelIdItem}

select s.accept_node as locationCode, s.industry_code, s.industry_name from sys_industry_conf s where s.industry_code in
#{code}
and s.delete_flag = '0'

select s.accept_node as locationCode, s.industry_code, s.industry_name from sys_localization_industry_conf s where s.industry_code in
#{code}
and s.delete_flag = '0'

select o.tenant_id, o.`accept_node` as locationCode,o.industry_code as industryCode,
o.app_ver_code as appVerCode
from vm_order_customer o
where o.delete_flag = 0 and o.ord_status in ('0', '1', '2')
and o.tenant_id = #{param.tenantId} and o.accept_node = #{param.acceptNode} and o.industry_code = #{param.industryCode}
and o.app_ver_code = #{param.appVerCode}

select o.tenant_id as "customerCode", o.`accept_node` as "locationCode",c.`platform_name` as "locationName",o.industry_code as "industryCode", o.app_ver_code as "appVerCode",count(o.accept_node) as "locationValidOrderNum" from vm_order_customer o inner join `vm_platform_data_config` c on o.`accept_node` = c.`platform_code` where o.delete_flag = 0 and c.`delete_flag` = 0 and o.ord_status in ('0', '1', '2') and o.tenant_id in
#{item}
GROUP BY o.tenant_id,locationCode,o.industry_code ,o.app_ver_code;

SELECT count( distinct device_code ) as "locationValidDevNum", tenant_id as "customerCode", accept_node as "locationCode", industry_code as "industryCode", app_ver_code as "appVerCode" FROM vm_order_devices WHERE delete_flag = '0' and ord_status in ('0','1','2') and tenant_id in
#{item}
GROUP BY tenant_id,accept_node ,industry_code ,app_ver_code;

select stoc.tenant_id, stoc.accept_node as locationCode, stoc.is_operation, case when stoc.is_operation = '0' then '未开启' else '开启' end isOperationName, stoc.industry_code, stoc.app_ver_code, stoc.delete_flag, stoc.update_time as operationModifierDate, stoc.modifier as operationModifier from sys_tenant_operation_config stoc where stoc.tenant_id in
#{item}
GROUP by stoc.tenant_id,stoc.accept_node,stoc.industry_code ,stoc.app_ver_code,stoc.delete_flag;

select s.accept_node, c.platform_name as acceptNodeName, s.push_status, s.tenant_id, s.industry_code, s.app_ver_code from sys_tenant_operation_push_record s left join vm_platform_data_config c on c.platform_code = s.accept_node where s.delete_flag = 0 and c.delete_flag = 0
and s.tenant_id = #{param.tenantId}
and s.industry_code = #{param.industryCode}
and s.app_ver_code = #{param.appVerCode}
and s.accept_node in
#{parentLocationCode}

