update
sys_tenant_operation_push_record s
set
s.push_time = #{item.pushTime},s.push_status = #{item.pushStatus},s.push_fail_reason = #{item.pushFailReason},
s.modifier = #{item.modifier},s.update_time = #{item.updateTime}
where
s.accept_node = #{item.acceptNode}
and s.tenant_id = #{item.tenantId}
and s.industry_code = #{item.industryCode}
and s.app_ver_code = #{item.appVerCode}
and s.delete_flag = 0

